-- LeadForge — initial schema
-- Target: MySQL 8.0+ / MariaDB 10.4+ (XAMPP). Charset utf8mb4.
-- All primary keys are UUID v4 strings (CHAR(36)) generated by the PHP layer.
-- Every tenant-owned table carries workspace_id for workspace-level isolation.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ---------------------------------------------------------------------------
-- Identity
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
  id                CHAR(36)      NOT NULL,
  email             VARCHAR(191)  NOT NULL,
  password_hash     VARCHAR(255)  NOT NULL,
  name              VARCHAR(120)  NOT NULL,
  status            ENUM('active','disabled') NOT NULL DEFAULT 'active',
  email_verified_at DATETIME      NULL,
  last_login_at     DATETIME      NULL,
  created_at        DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at        DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS profiles (
  user_id        CHAR(36)     NOT NULL,
  job_title      VARCHAR(120) NULL,
  company        VARCHAR(160) NULL,
  phone          VARCHAR(40)  NULL,
  timezone       VARCHAR(64)  NOT NULL DEFAULT 'UTC',
  currency       CHAR(3)      NOT NULL DEFAULT 'USD',
  default_city   VARCHAR(120) NULL,
  default_country VARCHAR(120) NULL,
  onboarded_at   DATETIME     NULL,
  created_at     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (user_id),
  CONSTRAINT fk_profiles_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS email_verifications (
  id          CHAR(36)  NOT NULL,
  user_id     CHAR(36)  NOT NULL,
  token_hash  CHAR(64)  NOT NULL,
  expires_at  DATETIME  NOT NULL,
  used_at     DATETIME  NULL,
  created_at  DATETIME  NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_email_verifications_token (token_hash),
  KEY idx_email_verifications_user (user_id),
  CONSTRAINT fk_email_verifications_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS password_resets (
  id          CHAR(36)  NOT NULL,
  user_id     CHAR(36)  NOT NULL,
  token_hash  CHAR(64)  NOT NULL,
  expires_at  DATETIME  NOT NULL,
  used_at     DATETIME  NULL,
  created_at  DATETIME  NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_password_resets_token (token_hash),
  KEY idx_password_resets_user (user_id),
  CONSTRAINT fk_password_resets_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Tenancy
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS workspaces (
  id          CHAR(36)     NOT NULL,
  name        VARCHAR(120) NOT NULL,
  slug        VARCHAR(140) NOT NULL,
  owner_id    CHAR(36)     NOT NULL,
  settings    JSON         NULL,
  created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_workspaces_slug (slug),
  KEY idx_workspaces_owner (owner_id),
  CONSTRAINT fk_workspaces_owner FOREIGN KEY (owner_id) REFERENCES users (id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS workspace_members (
  id            CHAR(36) NOT NULL,
  workspace_id  CHAR(36) NOT NULL,
  user_id       CHAR(36) NOT NULL,
  role          ENUM('owner','admin','member') NOT NULL DEFAULT 'member',
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_workspace_members (workspace_id, user_id),
  KEY idx_workspace_members_user (user_id),
  CONSTRAINT fk_wm_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE,
  CONSTRAINT fk_wm_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS subscriptions (
  id                    CHAR(36) NOT NULL,
  workspace_id          CHAR(36) NOT NULL,
  plan                  VARCHAR(40) NOT NULL DEFAULT 'free',
  status                ENUM('active','past_due','cancelled') NOT NULL DEFAULT 'active',
  limits                JSON NULL,
  current_period_start  DATETIME NOT NULL,
  current_period_end    DATETIME NULL,
  created_at            DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at            DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_subscriptions_workspace (workspace_id),
  CONSTRAINT fk_subscriptions_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS usage_records (
  id            CHAR(36) NOT NULL,
  workspace_id  CHAR(36) NOT NULL,
  user_id       CHAR(36) NULL,
  metric        ENUM('discovery_search','website_check','website_audit','lead_export') NOT NULL,
  quantity      INT UNSIGNED NOT NULL DEFAULT 1,
  recorded_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_usage_ws_metric_time (workspace_id, metric, recorded_at),
  CONSTRAINT fk_usage_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE,
  CONSTRAINT fk_usage_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Discovery
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS businesses (
  id                  CHAR(36)      NOT NULL,
  workspace_id        CHAR(36)      NOT NULL,
  osm_type            ENUM('node','way','relation') NOT NULL,
  osm_id              BIGINT UNSIGNED NOT NULL,
  name                VARCHAR(255)  NOT NULL,
  category            VARCHAR(60)   NOT NULL,
  street              VARCHAR(255)  NULL,
  city                VARCHAR(120)  NULL,
  postcode            VARCHAR(30)   NULL,
  country             VARCHAR(120)  NULL,
  phone               VARCHAR(80)   NULL,
  website             VARCHAR(500)  NULL,
  email               VARCHAR(191)  NULL,
  socials             JSON          NULL,
  opening_hours       VARCHAR(255)  NULL,
  lat                 DECIMAL(10,7) NOT NULL,
  lng                 DECIMAL(10,7) NOT NULL,
  website_status      ENUM('available','no_website','inactive','needs_review','unknown') NOT NULL DEFAULT 'unknown',
  website_http_status SMALLINT      NULL,
  website_checked_at  DATETIME      NULL,
  website_check_note  VARCHAR(255)  NULL,
  opportunity_score   TINYINT UNSIGNED NOT NULL DEFAULT 0,
  score_breakdown     JSON          NULL,
  raw_tags            JSON          NULL,
  discovered_at       DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at          DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_businesses_osm (workspace_id, osm_type, osm_id),
  KEY idx_businesses_ws_category (workspace_id, category),
  KEY idx_businesses_ws_score (workspace_id, opportunity_score),
  KEY idx_businesses_ws_status (workspace_id, website_status),
  KEY idx_businesses_ws_city (workspace_id, city),
  CONSTRAINT chk_businesses_score CHECK (opportunity_score <= 100),
  CONSTRAINT fk_businesses_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS saved_searches (
  id            CHAR(36)     NOT NULL,
  workspace_id  CHAR(36)     NOT NULL,
  user_id       CHAR(36)     NOT NULL,
  name          VARCHAR(120) NOT NULL,
  params        JSON         NOT NULL,
  result_count  INT UNSIGNED NULL,
  last_run_at   DATETIME     NULL,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_saved_searches_ws (workspace_id, created_at),
  CONSTRAINT fk_saved_searches_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE,
  CONSTRAINT fk_saved_searches_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Leads & CRM
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS leads (
  id            CHAR(36)      NOT NULL,
  workspace_id  CHAR(36)      NOT NULL,
  business_id   CHAR(36)      NULL,
  owner_id      CHAR(36)      NULL,
  name          VARCHAR(255)  NOT NULL,
  category      VARCHAR(60)   NULL,
  address       VARCHAR(500)  NULL,
  phone         VARCHAR(80)   NULL,
  email         VARCHAR(191)  NULL,
  website       VARCHAR(500)  NULL,
  status        ENUM('new','contacted','interested','qualified','proposal_sent','negotiation','won','lost') NOT NULL DEFAULT 'new',
  priority      ENUM('low','medium','high','urgent') NOT NULL DEFAULT 'medium',
  deal_value    DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  position      INT           NOT NULL DEFAULT 0,
  won_at        DATETIME      NULL,
  lost_at       DATETIME      NULL,
  lost_reason   VARCHAR(255)  NULL,
  created_at    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_leads_business (workspace_id, business_id),
  KEY idx_leads_ws_status (workspace_id, status, position),
  KEY idx_leads_ws_created (workspace_id, created_at),
  KEY idx_leads_ws_won (workspace_id, won_at),
  CONSTRAINT chk_leads_value CHECK (deal_value >= 0),
  CONSTRAINT fk_leads_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE,
  CONSTRAINT fk_leads_business FOREIGN KEY (business_id) REFERENCES businesses (id) ON DELETE SET NULL,
  CONSTRAINT fk_leads_owner FOREIGN KEY (owner_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tags (
  id            CHAR(36)    NOT NULL,
  workspace_id  CHAR(36)    NOT NULL,
  name          VARCHAR(50) NOT NULL,
  created_at    DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_tags_ws_name (workspace_id, name),
  CONSTRAINT fk_tags_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS lead_tags (
  lead_id  CHAR(36) NOT NULL,
  tag_id   CHAR(36) NOT NULL,
  PRIMARY KEY (lead_id, tag_id),
  KEY idx_lead_tags_tag (tag_id),
  CONSTRAINT fk_lead_tags_lead FOREIGN KEY (lead_id) REFERENCES leads (id) ON DELETE CASCADE,
  CONSTRAINT fk_lead_tags_tag FOREIGN KEY (tag_id) REFERENCES tags (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS contacts (
  id            CHAR(36)     NOT NULL,
  workspace_id  CHAR(36)     NOT NULL,
  lead_id       CHAR(36)     NULL,
  first_name    VARCHAR(80)  NOT NULL,
  last_name     VARCHAR(80)  NULL,
  job_title     VARCHAR(120) NULL,
  email         VARCHAR(191) NULL,
  phone         VARCHAR(40)  NULL,
  whatsapp      VARCHAR(40)  NULL,
  notes         TEXT         NULL,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_contacts_ws (workspace_id, last_name, first_name),
  KEY idx_contacts_lead (lead_id),
  CONSTRAINT fk_contacts_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE,
  CONSTRAINT fk_contacts_lead FOREIGN KEY (lead_id) REFERENCES leads (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS lead_notes (
  id            CHAR(36) NOT NULL,
  workspace_id  CHAR(36) NOT NULL,
  lead_id       CHAR(36) NOT NULL,
  user_id       CHAR(36) NULL,
  body          TEXT     NOT NULL,
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_lead_notes_lead (lead_id, created_at),
  KEY idx_lead_notes_ws (workspace_id),
  CONSTRAINT fk_lead_notes_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE,
  CONSTRAINT fk_lead_notes_lead FOREIGN KEY (lead_id) REFERENCES leads (id) ON DELETE CASCADE,
  CONSTRAINT fk_lead_notes_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS lead_activities (
  id               CHAR(36)     NOT NULL,
  workspace_id     CHAR(36)     NOT NULL,
  lead_id          CHAR(36)     NOT NULL,
  contact_id       CHAR(36)     NULL,
  user_id          CHAR(36)     NULL,
  type             ENUM('call','email','meeting','whatsapp','note','status_change','system') NOT NULL,
  direction        ENUM('inbound','outbound') NULL,
  subject          VARCHAR(255) NULL,
  body             TEXT         NULL,
  outcome          VARCHAR(120) NULL,
  duration_minutes SMALLINT UNSIGNED NULL,
  occurred_at      DATETIME     NOT NULL,
  created_at       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_lead_activities_lead (lead_id, occurred_at),
  KEY idx_lead_activities_ws (workspace_id, occurred_at),
  KEY idx_lead_activities_ws_type (workspace_id, type),
  CONSTRAINT fk_lead_activities_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE,
  CONSTRAINT fk_lead_activities_lead FOREIGN KEY (lead_id) REFERENCES leads (id) ON DELETE CASCADE,
  CONSTRAINT fk_lead_activities_contact FOREIGN KEY (contact_id) REFERENCES contacts (id) ON DELETE SET NULL,
  CONSTRAINT fk_lead_activities_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tasks (
  id            CHAR(36)     NOT NULL,
  workspace_id  CHAR(36)     NOT NULL,
  lead_id       CHAR(36)     NULL,
  assigned_to   CHAR(36)     NULL,
  created_by    CHAR(36)     NULL,
  title         VARCHAR(255) NOT NULL,
  description   TEXT         NULL,
  priority      ENUM('low','medium','high','urgent') NOT NULL DEFAULT 'medium',
  status        ENUM('todo','in_progress','done') NOT NULL DEFAULT 'todo',
  due_at        DATETIME     NULL,
  completed_at  DATETIME     NULL,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_tasks_ws_status_due (workspace_id, status, due_at),
  KEY idx_tasks_lead (lead_id),
  CONSTRAINT fk_tasks_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE,
  CONSTRAINT fk_tasks_lead FOREIGN KEY (lead_id) REFERENCES leads (id) ON DELETE CASCADE,
  CONSTRAINT fk_tasks_assignee FOREIGN KEY (assigned_to) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_tasks_creator FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS follow_ups (
  id            CHAR(36)     NOT NULL,
  workspace_id  CHAR(36)     NOT NULL,
  lead_id       CHAR(36)     NOT NULL,
  user_id       CHAR(36)     NULL,
  due_at        DATETIME     NOT NULL,
  channel       ENUM('call','email','meeting','whatsapp','other') NOT NULL DEFAULT 'call',
  note          VARCHAR(500) NULL,
  status        ENUM('pending','done','skipped') NOT NULL DEFAULT 'pending',
  completed_at  DATETIME     NULL,
  notified_at   DATETIME     NULL,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_follow_ups_ws_status_due (workspace_id, status, due_at),
  KEY idx_follow_ups_lead (lead_id),
  CONSTRAINT fk_follow_ups_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE,
  CONSTRAINT fk_follow_ups_lead FOREIGN KEY (lead_id) REFERENCES leads (id) ON DELETE CASCADE,
  CONSTRAINT fk_follow_ups_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS calendar_events (
  id            CHAR(36)     NOT NULL,
  workspace_id  CHAR(36)     NOT NULL,
  lead_id       CHAR(36)     NULL,
  user_id       CHAR(36)     NULL,
  title         VARCHAR(255) NOT NULL,
  description   TEXT         NULL,
  type          ENUM('meeting','call','demo','other') NOT NULL DEFAULT 'meeting',
  location      VARCHAR(255) NULL,
  starts_at     DATETIME     NOT NULL,
  ends_at       DATETIME     NOT NULL,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_calendar_ws_start (workspace_id, starts_at),
  CONSTRAINT chk_calendar_range CHECK (ends_at >= starts_at),
  CONSTRAINT fk_calendar_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_lead FOREIGN KEY (lead_id) REFERENCES leads (id) ON DELETE SET NULL,
  CONSTRAINT fk_calendar_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS email_templates (
  id            CHAR(36)     NOT NULL,
  workspace_id  CHAR(36)     NOT NULL,
  created_by    CHAR(36)     NULL,
  name          VARCHAR(120) NOT NULL,
  subject       VARCHAR(255) NOT NULL,
  body          TEXT         NOT NULL,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_email_templates_ws (workspace_id, name),
  CONSTRAINT fk_email_templates_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE,
  CONSTRAINT fk_email_templates_user FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS website_audits (
  id                CHAR(36)      NOT NULL,
  workspace_id      CHAR(36)      NOT NULL,
  business_id       CHAR(36)      NULL,
  lead_id           CHAR(36)      NULL,
  created_by        CHAR(36)      NULL,
  url               VARCHAR(500)  NOT NULL,
  final_url         VARCHAR(500)  NULL,
  status_code       SMALLINT      NULL,
  is_reachable      TINYINT(1)    NOT NULL DEFAULT 0,
  uses_https        TINYINT(1)    NOT NULL DEFAULT 0,
  response_time_ms  INT UNSIGNED  NULL,
  page_title        VARCHAR(500)  NULL,
  meta_description  VARCHAR(1000) NULL,
  has_viewport      TINYINT(1)    NOT NULL DEFAULT 0,
  has_favicon       TINYINT(1)    NOT NULL DEFAULT 0,
  has_canonical     TINYINT(1)    NOT NULL DEFAULT 0,
  h1_count          SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  html_lang         VARCHAR(20)   NULL,
  page_bytes        INT UNSIGNED  NULL,
  score             TINYINT UNSIGNED NOT NULL DEFAULT 0,
  checks            JSON          NULL,
  error             VARCHAR(255)  NULL,
  created_at        DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_website_audits_ws (workspace_id, created_at),
  KEY idx_website_audits_business (business_id),
  KEY idx_website_audits_lead (lead_id),
  CONSTRAINT fk_website_audits_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE,
  CONSTRAINT fk_website_audits_business FOREIGN KEY (business_id) REFERENCES businesses (id) ON DELETE SET NULL,
  CONSTRAINT fk_website_audits_lead FOREIGN KEY (lead_id) REFERENCES leads (id) ON DELETE SET NULL,
  CONSTRAINT fk_website_audits_user FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS notifications (
  id            CHAR(36)     NOT NULL,
  workspace_id  CHAR(36)     NOT NULL,
  user_id       CHAR(36)     NOT NULL,
  type          VARCHAR(40)  NOT NULL,
  title         VARCHAR(255) NOT NULL,
  body          VARCHAR(500) NULL,
  link          VARCHAR(255) NULL,
  read_at       DATETIME     NULL,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_notifications_user (workspace_id, user_id, read_at, created_at),
  CONSTRAINT fk_notifications_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE,
  CONSTRAINT fk_notifications_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- Infrastructure
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS rate_limits (
  bucket_key    VARCHAR(191) NOT NULL,
  hits          INT UNSIGNED NOT NULL DEFAULT 0,
  window_start  DATETIME     NOT NULL,
  PRIMARY KEY (bucket_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Response cache for public APIs (Overpass / Nominatim) to respect their usage policies.
CREATE TABLE IF NOT EXISTS api_cache (
  cache_key   CHAR(64)    NOT NULL,
  source      VARCHAR(30) NOT NULL,
  payload     MEDIUMTEXT  NOT NULL,
  expires_at  DATETIME    NOT NULL,
  created_at  DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (cache_key),
  KEY idx_api_cache_expires (expires_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS schema_migrations (
  version     VARCHAR(100) NOT NULL,
  applied_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (version)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
